insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$rosana$q$, $q$https://www.dosp.com.br/exibe_do.php?i=MjgyNDY1 (DOSP Rosana ed. 802, 06/09/2022: Decreto 3.503/2022) ; https://www.dosp.com.br/exibe_do.php?i=MjQxODMw (DOSP Rosana ed. 707, 13/04/2022: Decreto 3.462/2022, revogado)$q$, $q$Atos oficiais de Rosana: domínio público (Lei 9.610/1998 art. 8º IV). Registro revogado: limite municipal do IBGE (dados públicos, citar a fonte: IBGE).$q$, 1, $q$Dec. 3.503/2022, art. 1º: caminhões de carga pesada com mais de 2 eixos proibidos, sem horário, na Estrada da Jacutinga (Distrito de Primavera). A estrada não existe com esse nome no OpenStreetMap (nem em nome alternativo, varredura do PBF do Sudeste de 11/10/2026) e o ato não dá pontas nem referência: a regra entra desativada por falta de geometria confiável (pendência). O Dec. 3.462/2022 (primeira versão) fica como registro revogado.$q$);
